import React from 'react';
import './Hero.css';

export const Hero = () => {
  return (
    <section className="hero-section">

      {/* Layer 0 — Sky background */}
      <img
        src={process.env.PUBLIC_URL + '/bg%20hero.png'}
        alt=""
        className="hero-bg"
        aria-hidden="true"
      />

      {/* Layer 1 — Dark vignette overlay: darkens top & bottom, clears in the middle */}
      <div className="hero-vignette" aria-hidden="true" />

      {/* Layer 2 — Text & CTA */}
      <div className="nl-hero-content">
        <h1 className="nl-hero-heading">
          The intelligent travel companion<br />
          for <em>every journey you take.</em>
        </h1>
        <p className="nl-hero-subtitle">
          Your journey, our priority. Powered by AI, tailored for you.
        </p>
        <div className="nl-cta-row">
          <button id="nl-try-beta" className="nl-btn-hero-white">Join the Beta</button>
        </div>
      </div>

      {/* Layer 3 — Dashboard screenshot card (sits above text, below hills) */}
      <div className="hero-dashboard-wrapper">
        <img
          src={process.env.PUBLIC_URL + '/image%20(2).png'}
          alt="Dishastra app dashboard"
          className="hero-dashboard"
        />
      </div>

      {/* Layer 4 — Hills foreground (overlaps bottom third of dashboard) */}
      <div className="hero-hills-wrapper">
        <img
          src={process.env.PUBLIC_URL + '/image.png'}
          alt=""
          className="hero-hills"
          aria-hidden="true"
        />
      </div>

    </section>
  );
};
